```python
def shortest_superstring(a, b, c):
    def merge(s1, s2):
        # Merge s2 onto s1 if possible
        if s2 in s1:
            return s1
        for i in range(min(len(s1), len(s2)), 0, -1):
            if s1.endswith(s2[:i]):
                return s1 + s2[i:]
        return s1 + s2

    def superstring(x, y, z):
        # Merge three strings in given order
        return merge(merge(x, y), z)

    strings = [a, b, c]
    best = None

    # Try all permutations of the three strings
    from itertools import permutations
    for perm in permutations(strings):
        candidate = superstring(perm[0], perm[1], perm[2])
        if best is None or len(candidate) < len(best) or (len(candidate) == len(best) and candidate < best):
            best = candidate

    return best
```

