    from itertools import permutations

    def can_place(grid, tile_h, tile_w, r, c):
        if r + tile_h > H or c + tile_w > W:
            return False
        for i in range(r, r + tile_h):
            for j in range(c, c + tile_w):
                if grid[i][j]:
                    return False
        return True

    def place_tile(grid, tile_h, tile_w, r, c, value):
        for i in range(r, r + tile_h):
            for j in range(c, c + tile_w):
                grid[i][j] = value

    def backtrack(grid, tiles, idx):
        if idx == len(tiles):
            # Check if all cells are covered
            for i in range(H):
                for j in range(W):
                    if not grid[i][j]:
                        return False
            return True

        tile_h, tile_w = tiles[idx]

        # Try both orientations
        orientations = [(tile_h, tile_w), (tile_w, tile_h)]

        for h, w in orientations:
            for r in range(H):
                for c in range(W):
                    if can_place(grid, h, w, r, c):
                        # Place the tile
                        place_tile(grid, h, w, r, c, idx + 1)
                        if backtrack(grid, tiles, idx + 1):
                            return True
                        # Remove the tile
                        place_tile(grid, h, w, r, c, 0)

        # Try without using this tile
        if backtrack(grid, tiles, idx + 1):
            return True

        return False

    # Read input
    data = []
    for line in sys.stdin:
        data.append(line.strip())

    if not data:
        print("No")
        return

    first_line = data[0].split()
    N, H, W = int(first_line[0]), int(first_line[1]), int(first_line[2])

    tiles = []
    for i in range(1, N + 1):
        if i >= len(data):
            break
        a, b = map(int, data[i].split())
        tiles.append((a, b))

    # Create grid
    grid = [[0 for _ in range(W)] for _ in range(H)]

    # Try all permutations of tiles
    found = False
    for perm in permutations(tiles):
        # Reset grid
        grid = [[0 for _ in range(W)] for _ in range(H)]
        if backtrack(grid, perm, 0):
            found = True
            break

    print("Yes" if found else "No")

