def canSortArray(nums):
    def count_set_bits(n):
        count = 0
        while n:
            count += n & 1
            n >>= 1
        return count

    # Group elements by their set bit count and maintain relative order
    groups = []
    current_group = []
    current_bit_count = -1

    for num in nums:
        bit_count = count_set_bits(num)
        if bit_count == current_bit_count:
            current_group.append(num)
        else:
            if current_group:
                groups.append(current_group)
            current_group = [num]
            current_bit_count = bit_count

    # Don't forget the last group
    if current_group:
        groups.append(current_group)

    # Sort each group individually
    for group in groups:
        group.sort()

    # Flatten the groups back into an array
    sorted_nums = []
    for group in groups:
        sorted_nums.extend(group)

    # Check if the resulting array is sorted
    return sorted_nums == sorted(nums)
