```python
def beautifulIndices(s: str, a: str, b: str, k: int):
    len_a, len_b = len(a), len(b)
    n = len(s)

    # Find all starting indices where a matches
    indices_a = []
    for i in range(n - len_a + 1):
        if s[i:i + len_a] == a:
            indices_a.append(i)

    # Find all starting indices where b matches
    indices_b = []
    for j in range(n - len_b + 1):
        if s[j:j + len_b] == b:
            indices_b.append(j)

    # If no b matches, no beautiful indices
    if not indices_b:
        return []

    beautiful = []
    # For each a index, check if there exists a b index within k distance
    for i in indices_a:
        # Binary search to find nearest b index
        left, right = 0, len(indices_b) - 1
        found = False
        while left <= right:
            mid = (left + right) // 2
            j = indices_b[mid]
            if abs(j - i) <= k:
                found = True
                break
            elif j < i - k:
                left = mid + 1
            else:
                right = mid - 1
        if found:
            beautiful.append(i)

    return beautiful
