We can solve this by building a graph where each index is a node, and we connect indices if their gcd > 1.  
But checking all pairs would be O(n²), which is too slow for n up to 10⁵.

Instead, we can think in terms of prime factors:  
If two numbers share a prime factor, they can be connected via that prime.  
We can use a union-find (disjoint set union) structure to group indices that are connected through common prime factors.

**Approach:**
1. For each number, factorize it into its prime factors.
2. For each prime factor, connect the current index with the *first index* that had that prime factor (or connect all indices sharing that prime factor).
3. After processing, check if all indices are in the same connected component.

This way, we avoid O(n²) comparisons.

Here’s the Python implementation:

```python
from math import gcd
from collections import defaultdict

class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [1] * n

    def find(self, x):
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, x, y):
        rx, ry = self.find(x), self.find(y)
        if rx == ry:
            return
        if self.rank[rx] < self.rank[ry]:
            self.parent[rx] = ry
        elif self.rank[rx] > self.rank[ry]:
            self.parent[ry] = rx
        else:
            self.parent[ry] = rx
            self.rank[rx] += 1

def canTraverseAllPairs(nums):
    n = len(nums)
    if n == 1:
        return True

    dsu = DSU(n)
    prime_to_index = {}

    for i, num in enumerate(nums):
        if num == 1:
            return False  # gcd(1, anything) = 1, so can't connect

        d = 2
        x = num
        while d * d <= x:
            if x % d == 0:
                if d in prime_to_index:
                    dsu.union(i, prime_to_index[d])
                else:
                    prime_to_index[d] = i
                while x % d == 0:
                    x //= d
            d += 1
        if x > 1:  # remaining prime factor
            if x in prime_to_index:
                dsu.union(i, prime_to_index[x])
            else:
                prime_to_index[x] = i

    root = dsu.find(0)
    for i in range(1, n):
        if dsu.find(i) != root:
            return False
    return True
```

