Here's the solution:

```python
def specialPerm(nums):
    MOD = 10**9 + 7
    n = len(nums)

    # Precompute which pairs are valid (divisible in either direction)
    valid = [[False] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j and (nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0):
                valid[i][j] = True

    # dp[mask][last] = number of ways to arrange elements in mask ending with last element
    dp = [[0] * n for _ in range(1 << n)]

    # Initialize: single element permutations
    for i in range(n):
        dp[1 << i][i] = 1

    # Fill DP table
    for mask in range(1 << n):
        for last in range(n):
            if not (mask & (1 << last)):
                continue
            if dp[mask][last] == 0:
                continue

            # Try to add a new element
            for nxt in range(n):
                if mask & (1 << nxt):
                    continue  # Already used
                if not valid[last][nxt]:
                    continue  # Not divisible

                new_mask = mask | (1 << nxt)
                dp[new_mask][nxt] = (dp[new_mask][nxt] + dp[mask][last]) % MOD

    # Sum all permutations using all elements
    total = 0
    full_mask = (1 << n) - 1
    for last in range(n):
        total = (total + dp[full_mask][last]) % MOD

    return total
```

